public void run()
{
    CustVendorBlocked   blockStatus   = CustTable::find(this.salesTable().CustAccount).Blocked;

    // Verify if the CustAccount is blocked post sales invoice should not trigger
    if (blockStatus == CustVendorBlocked::METSalesinvoice)
    {
        throw warning(strFmt("@SYS18389", this.salesTable().CustAccount, enum2Str(blockStatus)));
    }

    next run();
}
